//! Checklist runner: validates framework seams, not real RPCS3 protocol compatibility.
use destiny_runtime_core::Runtime;use destiny_server_runtime::ServerRuntime;use destiny_test_client::TestClient;use std::sync::{Arc,Mutex};
#[derive(Debug,Clone,serde::Serialize)]pub struct Check{pub name:String,pub status:String,pub evidence:String}
pub fn run()->Vec<Check>{let db=Arc::new(Runtime::open(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../destiny.db")).unwrap());let server=Arc::new(Mutex::new(ServerRuntime::new(db)));let mut c=TestClient::default();let mut out=vec![];out.push(Check{name:"connection".into(),status:format!("{}",c.connect(server.clone()).is_ok()),evidence:"in-process framework connection".into()});out.push(Check{name:"session lifecycle".into(),status:format!("{}",c.create_session("rpcs3-test").and_then(|_|c.authenticate()).is_ok()),evidence:"placeholder authentication only".into()});out.push(Check{name:"definition request".into(),status:format!("{}",c.request_definition("80802797").is_ok()),evidence:"database-backed lookup seam".into()});for n in ["handshake","inventory","activity","world"]{out.push(Check{name:n.into(),status:"unknown".into(),evidence:"requires observed client protocol".into()});}out}
#[cfg(test)]mod tests{use super::*;#[test]fn checklist_marks_unknowns(){let r=run();assert!(r.iter().any(|c|c.name=="handshake"&&c.status=="unknown"));}}
